import { useEffect, useState } from 'react'
import { supabase } from './lib/supabase'
import RecipeVariants from './components/RecipeVariants.jsx'
import FamilyPage from './components/FamilyPage.jsx'
import FavoritesPage from './components/FavoritesPage.jsx'
import MediaSection from './components/MediaSection.jsx'
import CommentsSection from './components/CommentsSection.jsx'

const navigation = [
  { id: 'home', label: 'Accueil', icon: '⌂' },
  { id: 'recipes', label: 'Recettes', icon: '📖' },
  { id: 'grandma', label: 'Recettes de Mamie', icon: '👵' },
  { id: 'favorites', label: 'Favoris', icon: '♥' },
  { id: 'family', label: 'Famille', icon: '👨‍👩‍👧' },
]

const pages = {
  home: { kicker: 'Bienvenue', title: 'Des recettes transmises de génération en génération.', text: 'Retrouvez les recettes de la famille, les précieux écrits de Mamie, leurs adaptations et les souvenirs qui les accompagnent.' },
  grandma: { kicker: 'Le patrimoine de Mamie', title: 'Les recettes de Mamie', text: 'Les recettes originales, leurs documents manuscrits et les versions transmises aux générations suivantes.' },
}

function AuthPage({ onSignedIn }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const [resetOpen, setResetOpen] = useState(false); const [resetEmail, setResetEmail] = useState(''); const [resetLoading, setResetLoading] = useState(false); const [resetError, setResetError] = useState(''); const [resetMessage, setResetMessage] = useState(''); const [recoveryMode, setRecoveryMode] = useState(false); const [newPassword, setNewPassword] = useState(''); const [confirmPassword, setConfirmPassword] = useState('')
  useEffect(() => { if (!supabase) return; const { data } = supabase.auth.onAuthStateChange(event => { if (event === 'PASSWORD_RECOVERY') { setRecoveryMode(true); setResetOpen(false) } }); return () => data.subscription.unsubscribe() }, [])
  const signIn = async event => { event.preventDefault(); if (!supabase) return setError('La connexion Supabase n’est pas configurée.'); setLoading(true); setError(''); const { data, error: signInError } = await supabase.auth.signInWithPassword({ email, password }); if (signInError) setError(signInError.message); else onSignedIn(data.user); setLoading(false) }
  const sendReset = async event => { event.preventDefault(); if (!supabase) return; const address = resetEmail.trim(); if (!address) return; setResetLoading(true); setResetError(''); setResetMessage(''); const redirectTo = window.location.origin + window.location.pathname; const { error: resetRequestError } = await supabase.auth.resetPasswordForEmail(address, { redirectTo }); setResetLoading(false); if (resetRequestError) return setResetError(resetRequestError.message); setResetMessage('Si un compte correspond à cette adresse, un e-mail de réinitialisation vient d’être envoyé.') }
  const saveRecoveryPassword = async event => { event.preventDefault(); setResetError(''); if (newPassword.length < 8) return setResetError('Le nouveau mot de passe doit contenir au moins 8 caractères.'); if (newPassword !== confirmPassword) return setResetError('Les deux mots de passe ne correspondent pas.'); setResetLoading(true); const { error: updateError } = await supabase.auth.updateUser({ password: newPassword }); setResetLoading(false); if (updateError) return setResetError(updateError.message); setNewPassword(''); setConfirmPassword(''); setResetMessage('Votre mot de passe a été modifié. Vous pouvez maintenant continuer.'); setRecoveryMode(false) }
  if (recoveryMode) return <section className="auth-section"><div className="auth-card"><p className="section-kicker">Récupération du compte</p><h2>Nouveau mot de passe</h2><p>Choisissez un nouveau mot de passe pour votre compte.</p><form onSubmit={saveRecoveryPassword} className="recipe-form"><label>Nouveau mot de passe<input type="password" minLength="8" value={newPassword} onChange={e => setNewPassword(e.target.value)} required autoComplete="new-password" /></label><label>Confirmer le mot de passe<input type="password" minLength="8" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required autoComplete="new-password" /></label>{resetError && <div className="form-error">{resetError}</div>}<button className="primary-button" type="submit" disabled={resetLoading}>{resetLoading ? 'Modification…' : 'Enregistrer le nouveau mot de passe'}</button></form></div></section>
  return <section className="auth-section"><div className="auth-card"><p className="section-kicker">Livre familial privé</p><h2>Bienvenue dans votre livre</h2><p>Connectez-vous pour retrouver et enrichir les recettes de la famille.</p><form onSubmit={signIn} className="recipe-form"><label>Email<input type="email" value={email} onChange={e => setEmail(e.target.value)} required autoComplete="email" /></label><label>Mot de passe<input type="password" value={password} onChange={e => setPassword(e.target.value)} required autoComplete="current-password" /></label><button type="button" className="forgot-password-button" onClick={() => { setResetEmail(email); setResetOpen(true); setResetError(''); setResetMessage('') }}>Mot de passe oublié ?</button>{error && <div className="form-error">{error}</div>}<button className="primary-button" type="submit" disabled={loading}>{loading ? 'Connexion…' : 'Se connecter'}</button></form></div>{resetOpen && <div className="password-modal-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget && !resetLoading) setResetOpen(false) }}><div className="password-modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><button type="button" className="password-modal-close" onClick={() => setResetOpen(false)} aria-label="Fermer">×</button><p className="section-kicker">Récupération du compte</p><h3 id="reset-title">Mot de passe oublié ?</h3><p className="password-modal-intro">Indiquez votre adresse e-mail. Nous vous enverrons un lien pour choisir un nouveau mot de passe.</p><form onSubmit={sendReset}><label>Adresse e-mail<input type="email" value={resetEmail} onChange={event => setResetEmail(event.target.value)} required autoComplete="email" /></label>{resetError && <p className="password-form-error" role="alert">{resetError}</p>}{resetMessage && <p className="password-form-success" role="status">{resetMessage}</p>}<div className="password-modal-actions"><button type="button" className="secondary-button" onClick={() => setResetOpen(false)} disabled={resetLoading}>Annuler</button><button type="submit" className="primary-button" disabled={resetLoading || !!resetMessage}>{resetLoading ? 'Envoi…' : resetMessage ? 'E-mail envoyé' : 'Envoyer le lien'}</button></div></form></div></div>}</section>
}

function RecipesPage({ recipes, loading, error, onRetry, onAdd, onOpen, canEdit, user }) {
  const [favoriteIds, setFavoriteIds] = useState(new Set()); const [favoriteLoadingId, setFavoriteLoadingId] = useState(null); const [sortBy, setSortBy] = useState('recent'); const [categoryFilter, setCategoryFilter] = useState('all'); const [tagFilter, setTagFilter] = useState(''); const [searchQuery, setSearchQuery] = useState(''); const [searchFocused, setSearchFocused] = useState(false); const [recipeIngredients, setRecipeIngredients] = useState({}); const [variantIngredients, setVariantIngredients] = useState({}); const [variantMatches, setVariantMatches] = useState({})
  useEffect(() => { let cancelled = false; const loadFavorites = async () => { if (!supabase || !user) return; const { data, error: favoriteError } = await supabase.from('favorites').select('recipe_id').eq('user_id', user.id); if (!cancelled && !favoriteError) setFavoriteIds(new Set((data ?? []).map(item => item.recipe_id))) }; loadFavorites(); return () => { cancelled = true } }, [user?.id, recipes])
  useEffect(() => { let cancelled = false; const loadIngredients = async () => { if (!supabase || recipes.length === 0) { setRecipeIngredients({}); setVariantIngredients({}); setVariantMatches({}); return }; const ids = recipes.map(recipe => recipe.id); const { data: versions } = await supabase.from('recipe_versions').select('id, recipe_id, is_original').in('recipe_id', ids); if (!versions?.length) { if (!cancelled) { setRecipeIngredients({}); setVariantIngredients({}); setVariantMatches({}) }; return }; const versionInfo = new Map(versions.map(version => [version.id, version])); const { data: ingredients } = await supabase.from('ingredients').select('version_id, name').in('version_id', versions.map(version => version.id)); const grouped = {}; const variants = {}; const variantDetails = {}; (ingredients ?? []).forEach(ingredient => { const version = versionInfo.get(ingredient.version_id); if (!version) return; if (!grouped[version.recipe_id]) grouped[version.recipe_id] = []; grouped[version.recipe_id].push(ingredient.name); if (!version.is_original) { if (!variants[version.recipe_id]) variants[version.recipe_id] = []; variants[version.recipe_id].push(ingredient.name); if (!variantDetails[version.recipe_id]) variantDetails[version.recipe_id] = []; variantDetails[version.recipe_id].push({ versionId: version.id, name: ingredient.name }) } }); if (!cancelled) { setRecipeIngredients(grouped); setVariantIngredients(variants); setVariantMatches(variantDetails) } }; loadIngredients(); return () => { cancelled = true } }, [recipes])
  const usedCategories = [...new Map(recipes.filter(recipe => recipe.category_id && recipe.categories?.name).map(recipe => [recipe.category_id, recipe.categories.name])).entries()].sort((a, b) => a[1].localeCompare(b[1], 'fr'))
  const hasUnclassified = recipes.some(recipe => !recipe.category_id)
  const normalizeSearch = value => (value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr').replace(/[^a-z0-9]+/g, ' ').trim()
  const normalizedSearch = normalizeSearch(searchQuery)
  const searchTerms = normalizedSearch.split(' ').filter(Boolean)
  const searchableValues = recipe => [recipe.title, recipe.description, recipe.original_author, recipe.categories?.name, ...(recipe.tags ?? []), ...(recipeIngredients[recipe.id] ?? [])].filter(Boolean).map(normalizeSearch)
  const matchesSearch = recipe => searchTerms.length === 0 || searchTerms.every(term => searchableValues(recipe).some(value => value.includes(term)))
  const suggestionValues = [...new Set(recipes.flatMap(recipe => [recipe.title, recipe.original_author, ...(recipe.tags ?? []), ...(recipeIngredients[recipe.id] ?? [])]).filter(Boolean))]
  const suggestions = normalizedSearch.length >= 2 ? suggestionValues.filter(value => searchTerms.every(term => normalizeSearch(value).includes(term)) && normalizeSearch(value) !== normalizedSearch).slice(0, 5) : []
  const categoryRecipes = categoryFilter === 'all' ? recipes : categoryFilter === 'unclassified' ? recipes.filter(recipe => !recipe.category_id) : recipes.filter(recipe => recipe.category_id === categoryFilter)
  const tagRecipes = tagFilter ? categoryRecipes.filter(recipe => (recipe.tags ?? []).some(tag => normalizeSearch(tag) === normalizeSearch(tagFilter))) : categoryRecipes
  const filteredRecipes = tagRecipes.filter(matchesSearch)
  const sortedRecipes = [...filteredRecipes].sort((a, b) => sortBy === 'title' ? (a.title || '').localeCompare(b.title || '', 'fr') : sortBy === 'quick' ? ((a.preparation_time_minutes ?? 9999) + (a.cooking_time_minutes ?? 9999)) - ((b.preparation_time_minutes ?? 9999) + (b.cooking_time_minutes ?? 9999)) : new Date(b.created_at) - new Date(a.created_at))
  const toggleFavorite = async (event, recipe) => { event.stopPropagation(); if (!supabase || !user || favoriteLoadingId) return; setFavoriteLoadingId(recipe.id); try { if (favoriteIds.has(recipe.id)) { const { error: favoriteError } = await supabase.from('favorites').delete().eq('user_id', user.id).eq('recipe_id', recipe.id); if (favoriteError) throw favoriteError; setFavoriteIds(current => { const next = new Set(current); next.delete(recipe.id); return next }) } else { const { data: recipeData, error: recipeError } = await supabase.from('recipes').select('family_id').eq('id', recipe.id).single(); if (recipeError) throw recipeError; const { error: favoriteError } = await supabase.from('favorites').insert({ user_id: user.id, recipe_id: recipe.id, family_id: recipeData.family_id }); if (favoriteError) throw favoriteError; setFavoriteIds(current => new Set([...current, recipe.id])) } } catch (favoriteError) { console.error('Erreur favori:', favoriteError) } finally { setFavoriteLoadingId(null) } }
  return <section className="recipes-section"><div className="section-heading"><div><p className="section-kicker">Le livre familial</p><h3>Toutes les recettes</h3></div><div className="section-heading-actions">{canEdit && <button type="button" className="primary-button small-button" onClick={onAdd}>＋ Ajouter une recette</button>}{!loading && recipes.length > 0 && <span className="recipe-count">{recipes.length} recette{recipes.length > 1 ? 's' : ''}</span>}</div></div>{!loading && !error && recipes.length > 0 && <div className="recipe-search-wrap"><div className="recipe-search"><span aria-hidden="true">⌕</span><input type="search" value={searchQuery} onChange={event => setSearchQuery(event.target.value)} onFocus={() => setSearchFocused(true)} onBlur={() => window.setTimeout(() => setSearchFocused(false), 120)} placeholder="Recette, auteur, tag ou ingrédient…" aria-label="Rechercher une recette, un auteur, un tag ou un ingrédient" autoComplete="off" />{searchQuery && <button type="button" onClick={() => setSearchQuery('')} aria-label="Effacer la recherche">×</button>}</div>{searchFocused && suggestions.length > 0 && <div className="recipe-search-suggestions">{suggestions.map(suggestion => <button type="button" key={suggestion} onMouseDown={event => event.preventDefault()} onClick={() => { setSearchQuery(suggestion); setSearchFocused(false) }}><span aria-hidden="true">⌕</span>{suggestion}</button>)}</div>}</div>}{!loading && !error && recipes.length > 0 && <div className="recipe-filters" aria-label="Filtrer les recettes par catégorie"><button type="button" className={categoryFilter === 'all' ? 'recipe-filter active' : 'recipe-filter'} onClick={() => setCategoryFilter('all')}>Toutes</button>{usedCategories.map(([id, name]) => <button type="button" key={id} className={categoryFilter === id ? 'recipe-filter active' : 'recipe-filter'} onClick={() => setCategoryFilter(id)}>{name}</button>)}{hasUnclassified && <button type="button" className={categoryFilter === 'unclassified' ? 'recipe-filter active' : 'recipe-filter'} onClick={() => setCategoryFilter('unclassified')}>Non classées</button>}</div>}{!loading && !error && recipes.length > 1 && <div className="recipe-sort"><label htmlFor="recipe-sort-select">Trier par</label><select id="recipe-sort-select" value={sortBy} onChange={event => setSortBy(event.target.value)}><option value="recent">Plus récentes</option><option value="title">Nom A–Z</option><option value="quick">Temps total</option></select></div>}{tagFilter && <div className="active-tag-filter"><span>Tag : #{tagFilter}</span><button type="button" onClick={() => setTagFilter('')} aria-label={`Retirer le filtre ${tagFilter}`}>×</button></div>}{loading && <div className="status-card">Chargement des recettes…</div>}{!loading && error && <div className="status-card error-card"><strong>Impossible de charger les recettes.</strong><p>{error}</p><button type="button" className="secondary-button" onClick={onRetry}>Réessayer</button></div>}{!loading && !error && recipes.length === 0 && <div className="status-card empty-card"><span className="empty-icon">📖</span><h4>{canEdit ? 'Votre livre commence ici' : 'Aucune recette pour le moment'}</h4><p>{canEdit ? 'Aucune recette n’est encore enregistrée. Ajoutez votre première recette familiale.' : 'Aucune recette familiale n’est encore enregistrée.'}</p>{canEdit && <button type="button" className="primary-button" onClick={onAdd}>Ajouter la première recette</button>}</div>}{!loading && !error && recipes.length > 0 && (sortedRecipes.length > 0 ? <div className="recipe-grid">{sortedRecipes.map(recipe => <div className="recipe-card" key={recipe.id}><button className="recipe-card-open" type="button" onClick={() => { const matchedVariant = searchTerms.length ? (variantMatches[recipe.id] ?? []).find(item => searchTerms.some(term => normalizeSearch(item.name).includes(term))) : null; onOpen(recipe.id, matchedVariant?.versionId || null) }}><div className="recipe-card-body">{recipe.categories?.name && <span className="category-badge">{recipe.categories.name}</span>}<div className="recipe-card-meta">{recipe.original_author && <span>{recipe.original_author}</span>}{recipe.origin_year && <span>{recipe.origin_year}</span>}</div><h4>{recipe.title}</h4>{recipe.description && <p>{recipe.description}</p>}{recipe.tags?.length > 0 && <div className="recipe-tags compact">{recipe.tags.slice(0, 3).map(tag => <button type="button" key={tag} className={normalizeSearch(tagFilter) === normalizeSearch(tag) ? "active" : ""} onClick={event => { event.stopPropagation(); setTagFilter(tag); setSearchQuery(""); }} aria-label={`Filtrer par le tag ${tag}`}>#{tag}</button>)}</div>}{normalizedSearch && (variantIngredients[recipe.id] ?? []).some(value => normalizeSearch(value).includes(normalizedSearch)) && <span className="variant-search-match">Trouvé dans une variante</span>}<div className="recipe-card-footer"><span>{recipe.servings ? `👨‍👩‍👧‍👦 ${recipe.servings} pers.` : 'Recette familiale'}</span>{recipe.difficulty && <span>{recipe.difficulty}</span>}</div></div></button><button type="button" className={`recipe-card-favorite ${favoriteIds.has(recipe.id) ? 'is-favorite' : ''}`} onClick={event => toggleFavorite(event, recipe)} disabled={favoriteLoadingId === recipe.id} aria-label={favoriteIds.has(recipe.id) ? 'Retirer des favoris' : 'Ajouter aux favoris'} title={favoriteIds.has(recipe.id) ? 'Retirer des favoris' : 'Ajouter aux favoris'}>{favoriteIds.has(recipe.id) ? '♥' : '♡'}</button></div>)}</div> : <div className="status-card empty-card"><p>{searchQuery.trim() ? 'Aucune recette ne correspond à votre recherche.' : 'Aucune recette dans cette catégorie.'}</p></div>)}</section>
}

function GrandmaPage({ recipes, loading, error, onRetry, onOpen }) {
  const [manuscripts, setManuscripts] = useState(new Set())
  const grandmaRecipes = recipes.filter(recipe => { const author = (recipe.original_author || '').toLowerCase(); return author.includes('mamie') || author.includes('grand-maman') || author.includes('grand maman') })
  useEffect(() => {
    let cancelled = false
    const loadManuscripts = async () => {
      if (!supabase || grandmaRecipes.length === 0) { setManuscripts(new Set()); return }
      const { data } = await supabase.from('media').select('recipe_id').in('recipe_id', grandmaRecipes.map(recipe => recipe.id)).eq('media_type', 'scan')
      if (!cancelled) setManuscripts(new Set((data ?? []).map(item => item.recipe_id)))
    }
    loadManuscripts()
    return () => { cancelled = true }
  }, [recipes])
  return <section className="recipes-section"><div className="section-heading"><div><p className="section-kicker">Le patrimoine de Mamie</p><h3>Les recettes de Mamie</h3><p className="hero-text">Retrouvez les recettes dont Mamie est à l’origine, avec leur année, leur histoire et, lorsqu’il existe, leur manuscrit original.</p></div>{!loading && !error && <span className="recipe-count">{grandmaRecipes.length} recette{grandmaRecipes.length > 1 ? 's' : ''}</span>}</div>{loading && <div className="status-card">Chargement des recettes de Mamie…</div>}{!loading && error && <div className="status-card error-card"><strong>Impossible de charger les recettes.</strong><p>{error}</p><button type="button" className="secondary-button" onClick={onRetry}>Réessayer</button></div>}{!loading && !error && grandmaRecipes.length === 0 && <div className="status-card empty-card"><span className="empty-icon">👵</span><h4>Aucune recette de Mamie pour le moment</h4><p>Les recettes apparaîtront ici dès qu’elles seront renseignées avec « Mamie » ou « Grand-Maman » comme auteur d’origine.</p></div>}{!loading && !error && grandmaRecipes.length > 0 && <div className="recipe-grid">{grandmaRecipes.map(recipe => <button className="recipe-card" key={recipe.id} type="button" onClick={() => onOpen(recipe.id)}><div className="recipe-card-image" aria-hidden="true">👵</div><div className="recipe-card-body"><div className="recipe-card-meta"><span>{recipe.original_author}</span>{recipe.origin_year && <span>{recipe.origin_year}</span>}{manuscripts.has(recipe.id) && <span>✍️ Manuscrit conservé</span>}</div><h4>{recipe.title}</h4>{recipe.description && <p>{recipe.description}</p>}<div className="recipe-card-footer"><span>Recette originale</span>{recipe.servings && <span>👨‍👩‍👧‍👦 {recipe.servings} pers.</span>}</div></div></button>)}</div>}</section>
}

function RecipeDetailPage({ recipeId, initialVersionId, user, onBack, onEdit }) {
  const [recipe, setRecipe] = useState(null); const [canManageRecipe, setCanManageRecipe] = useState(false); const [canEditVariants, setCanEditVariants] = useState(false); const [requestedVariantEditId, setRequestedVariantEditId] = useState(null); const [editWarningOpen, setEditWarningOpen] = useState(false); const [hasVariants, setHasVariants] = useState(false); const [version, setVersion] = useState(null); const [isFavorite, setIsFavorite] = useState(false); const [favoriteLoading, setFavoriteLoading] = useState(false); const [ingredients, setIngredients] = useState([]); const [steps, setSteps] = useState([]); const [loading, setLoading] = useState(true); const [switchingVersion, setSwitchingVersion] = useState(false); const [error, setError] = useState('')
  const loadVersion = async versionId => { const { data: versionData, error: versionError } = await supabase.from('recipe_versions').select('id, version_name, notes, is_original, based_on_version_id, created_at, updated_at').eq('id', versionId).eq('recipe_id', recipeId).single(); if (versionError) throw versionError; const [ingredientsResult, stepsResult] = await Promise.all([supabase.from('ingredients').select('id, position, quantity, unit, name, notes').eq('version_id', versionData.id).order('position', { ascending: true }), supabase.from('preparation_steps').select('id, position, instruction, duration_minutes, temperature_celsius').eq('version_id', versionData.id).order('position', { ascending: true })]); if (ingredientsResult.error) throw ingredientsResult.error; if (stepsResult.error) throw stepsResult.error; return { version: versionData, ingredients: ingredientsResult.data ?? [], steps: stepsResult.data ?? [] } }
  useEffect(() => { const loadFavorite = async () => { if (!supabase || !user || !recipe?.id) return; const { data, error } = await supabase.from('favorites').select('recipe_id').eq('user_id', user.id).eq('recipe_id', recipe.id).maybeSingle(); if (!error) setIsFavorite(!!data) }; loadFavorite() }, [user?.id, recipe?.id])
  const toggleFavorite = async () => { if (!supabase || !user || !recipeId || favoriteLoading) return; setFavoriteLoading(true); try { if (isFavorite) { const { error } = await supabase.from('favorites').delete().eq('user_id', user.id).eq('recipe_id', recipeId); if (error) throw error; setIsFavorite(false) } else { const { error } = await supabase.from('favorites').insert({ user_id: user.id, recipe_id: recipe.id, family_id: recipe.family_id }); if (error) throw error; setIsFavorite(true) } } catch (favoriteError) { console.error('Erreur favori:', favoriteError); setError(favoriteError.message || 'Impossible de modifier les favoris.') } finally { setFavoriteLoading(false) } }
  useEffect(() => { let cancelled = false; const load = async () => { if (!supabase || !recipeId) return; setLoading(true); setError(''); try { const { data: recipeData, error: recipeError } = await supabase.from('recipes').select('id, family_id, category_id, title, description, original_author, origin_year, difficulty, servings, preparation_time_minutes, cooking_time_minutes, tags, created_by, created_at, categories(name)').eq('id', recipeId).single(); if (recipeError) throw recipeError; const { data: membership } = await supabase.from('family_members').select('id, role').eq('user_id', user.id).eq('family_id', recipeData.family_id).eq('is_active', true).maybeSingle(); if (!cancelled) { setCanManageRecipe(!!membership && (membership.role === 'admin' || membership.id === recipeData.created_by)); setCanEditVariants(!!membership && ['admin', 'editor'].includes(membership.role)); } const { count: variantCount } = await supabase.from('recipe_versions').select('id', { count: 'exact', head: true }).eq('recipe_id', recipeId).eq('is_original', false); if (!cancelled) setHasVariants((variantCount ?? 0) > 0); let versionData; if (initialVersionId) { const result = await supabase.from('recipe_versions').select('id').eq('id', initialVersionId).eq('recipe_id', recipeId).maybeSingle(); if (result.error) throw result.error; versionData = result.data } if (!versionData) { const result = await supabase.from('recipe_versions').select('id').eq('recipe_id', recipeId).eq('is_original', true).order('created_at', { ascending: true }).limit(1).maybeSingle(); if (result.error) throw result.error; versionData = result.data } if (!versionData) throw new Error('Cette recette ne contient pas encore de version originale.'); const selected = await loadVersion(versionData.id); if (!cancelled) { setRecipe(recipeData); setVersion(selected.version); setIngredients(selected.ingredients); setSteps(selected.steps) } } catch (loadError) { if (!cancelled) setError(loadError.message || 'Impossible de charger cette recette.') } finally { if (!cancelled) setLoading(false) } }; load(); return () => { cancelled = true } }, [recipeId, initialVersionId])
  const handleSelectVersion = async versionId => { if (!supabase || !versionId || versionId === version?.id) return; setSwitchingVersion(true); setError(''); try { const selected = await loadVersion(versionId); setVersion(selected.version); setIngredients(selected.ingredients); setSteps(selected.steps); window.scrollTo({ top: 0, behavior: 'smooth' }) } catch (loadError) { setError(loadError.message || 'Impossible de charger cette version.') } finally { setSwitchingVersion(false) } }
  if (loading) return <section className="detail-section"><button type="button" className="secondary-button back-button" onClick={onBack}>← Retour aux recettes</button><div className="status-card">Chargement de la recette…</div></section>
  if (error && !recipe) return <section className="detail-section"><button type="button" className="secondary-button back-button" onClick={onBack}>← Retour aux recettes</button><div className="status-card error-card"><strong>Impossible de charger la recette.</strong><p>{error}</p></div></section>
  if (!recipe) return null
  const difficultyLabel = { facile: 'Facile', moyenne: 'Moyenne', difficile: 'Difficile' }[recipe.difficulty] || recipe.difficulty
  return <section className="detail-section"><button type="button" className="secondary-button back-button" onClick={onBack}>← Retour aux recettes</button><article className="recipe-detail"><div className="recipe-detail-actions"><button type="button" className={`recipe-detail-icon-button recipe-favorite-icon ${isFavorite ? 'is-favorite' : ''}`} onClick={toggleFavorite} disabled={favoriteLoading} aria-label={isFavorite ? 'Retirer des favoris' : 'Ajouter aux favoris'} title={isFavorite ? 'Retirer des favoris' : 'Ajouter aux favoris'}>{isFavorite ? '♥' : '♡'}</button>{((version?.is_original && canManageRecipe) || (!version?.is_original && canEditVariants)) && <button type="button" className="recipe-detail-icon-button recipe-edit-icon" onClick={() => version?.is_original ? setEditWarningOpen(true) : setRequestedVariantEditId(version.id)} aria-label={version?.is_original ? 'Modifier la recette originale' : 'Modifier cette variante'} title={version?.is_original ? 'Modifier la recette originale' : 'Modifier cette variante'}>✎</button>}</div>{editWarningOpen && <div className="recipe-edit-warning-backdrop" role="presentation" onClick={() => setEditWarningOpen(false)}><div className="recipe-edit-warning" role="alertdialog" aria-modal="true" aria-labelledby="edit-original-title" onClick={event => event.stopPropagation()}><div className="recipe-edit-warning-icon">!</div><h3 id="edit-original-title">Modifier la recette originale ?</h3><p>Cette recette constitue la version originale conservée dans le livre familial. Sa modification doit rester exceptionnelle, par exemple pour corriger une erreur de frappe ou de retranscription.</p>{hasVariants && <p className="recipe-edit-warning-note">Des variantes existent déjà pour cette recette. Pour une adaptation de la recette, privilégiez l’ajout d’une nouvelle variante afin de préserver l’originale.</p>}<div className="recipe-edit-warning-actions"><button type="button" className="secondary-button" onClick={() => setEditWarningOpen(false)}>Annuler</button><button type="button" className="primary-button" onClick={() => { setEditWarningOpen(false); onEdit(recipeId) }}>Modifier quand même</button></div></div></div>}<header className="detail-header no-cover"><div className="detail-intro"><div className="detail-kicker-row"><p className="section-kicker">{version?.is_original ? 'Recette originale' : 'Variante familiale'}</p>{recipe.categories?.name && <span className="category-badge">{recipe.categories.name}</span>}</div><h2>{recipe.title}</h2>{version?.version_name && <p className="detail-version-name">{version.version_name}</p>}{recipe.description && <p className="detail-description">{recipe.description}</p>}{recipe.tags?.length > 0 && <div className="recipe-tags detail-tags">{recipe.tags.map(tag => <span key={tag}>#{tag}</span>)}</div>}<div className="detail-meta">{recipe.original_author && <span>👵 {recipe.original_author}</span>}{recipe.origin_year && <span>📅 {recipe.origin_year}</span>}{recipe.servings && <span>👨‍👩‍👧‍👦 {recipe.servings} personnes</span>}{recipe.preparation_time_minutes != null && <span>Préparation {recipe.preparation_time_minutes} min</span>}{recipe.cooking_time_minutes != null && <span>Cuisson {recipe.cooking_time_minutes} min</span>}{difficultyLabel && <span>◎ {difficultyLabel}</span>}</div></div></header>{error && <div className="form-error">{error}</div>}{switchingVersion && <div className="status-card">Chargement de la version sélectionnée…</div>}<div className="detail-content"><section className="detail-panel"><div className="detail-panel-heading"><p className="section-kicker">Les ingrédients</p><h3>Pour préparer cette recette</h3></div>{ingredients.length === 0 ? <p className="muted-text">Aucun ingrédient renseigné.</p> : <ul className="detail-ingredients">{ingredients.map(item => <li key={item.id}><span className="ingredient-amount">{item.quantity ?? ''}{item.quantity != null && item.unit ? ` ${item.unit}` : item.unit || ''}</span><span className="ingredient-name">{item.name}</span>{item.notes && <span className="ingredient-note">{item.notes}</span>}</li>)}</ul>}</section><section className="detail-panel"><div className="detail-panel-heading"><p className="section-kicker">La préparation</p><h3>Étape par étape</h3></div>{steps.length === 0 ? <p className="muted-text">Aucune étape renseignée.</p> : <ol className="detail-steps">{steps.map((step, index) => <li key={step.id}><div className="detail-step-number">{index + 1}</div><div><p>{step.instruction}</p>{(step.duration_minutes != null || step.temperature_celsius != null) && <div className="step-meta">{step.duration_minutes != null && <span>⏱ {step.duration_minutes} min</span>}{step.temperature_celsius != null && <span>🌡 {step.temperature_celsius} °C</span>}</div>}</div></li>)}</ol>}</section></div><MediaSection recipeId={recipeId} user={user} /><CommentsSection recipeId={recipeId} user={user} /><RecipeVariants recipeId={recipeId} user={user} currentVersionId={version?.id} onSelectVersion={handleSelectVersion} requestedEditingVersionId={requestedVariantEditId} onEditingRequestHandled={() => setRequestedVariantEditId(null)} /></article></section>
}

const emptyIngredient = () => ({ quantity: '', unit: '', name: '', notes: '' }); const emptyStep = () => ({ instruction: '', duration_minutes: '', temperature_celsius: '' })
function AddRecipePage({ user, onCancel, onCreated, recipeId = null }) {
  const isEditing = !!recipeId; const [form, setForm] = useState({ title: '', description: '', original_author: '', origin_year: '', difficulty: '', servings: '', preparation_time_minutes: '', cooking_time_minutes: '', category_id: '', tags: '' }); const [categories, setCategories] = useState([]); const [ingredients, setIngredients] = useState([emptyIngredient()]); const [steps, setSteps] = useState([emptyStep()]); const [loading, setLoading] = useState(false); const [error, setError] = useState('')
  useEffect(() => { const loadCategories = async () => { if (!supabase || !user) return; const { data: membership } = await supabase.from('family_members').select('family_id').eq('user_id', user.id).eq('is_active', true).limit(1).maybeSingle(); if (!membership) return; const { data } = await supabase.from('categories').select('id, name').eq('family_id', membership.family_id).order('name'); setCategories(data ?? []) }; loadCategories() }, [user?.id])
  useEffect(() => { const loadRecipeForEdit = async () => { if (!isEditing || !supabase) return; setLoading(true); setError(''); try { const { data: recipe, error: recipeError } = await supabase.from('recipes').select('id, family_id, category_id, title, description, original_author, origin_year, difficulty, servings, preparation_time_minutes, cooking_time_minutes, tags, created_by').eq('id', recipeId).single(); if (recipeError) throw recipeError; const { data: membership } = await supabase.from('family_members').select('id, role').eq('user_id', user.id).eq('family_id', recipe.family_id).eq('is_active', true).maybeSingle(); if (!membership || (membership.role !== 'admin' && membership.id !== recipe.created_by)) throw new Error('Vous ne pouvez pas modifier cette recette.'); const { data: version, error: versionError } = await supabase.from('recipe_versions').select('id').eq('recipe_id', recipeId).eq('is_original', true).order('created_at').limit(1).maybeSingle(); if (versionError || !version) throw new Error(versionError?.message || 'Version originale introuvable.'); const [ings, sts] = await Promise.all([supabase.from('ingredients').select('quantity,unit,name,notes').eq('version_id', version.id).order('position'), supabase.from('preparation_steps').select('instruction,duration_minutes,temperature_celsius').eq('version_id', version.id).order('position')]); if (ings.error) throw ings.error; if (sts.error) throw sts.error; setForm({ title: recipe.title || '', description: recipe.description || '', original_author: recipe.original_author || '', origin_year: recipe.origin_year || '', difficulty: recipe.difficulty || '', servings: recipe.servings || '', preparation_time_minutes: recipe.preparation_time_minutes ?? '', cooking_time_minutes: recipe.cooking_time_minutes ?? '', category_id: recipe.category_id || '', tags: (recipe.tags ?? []).join(', ') }); setIngredients(ings.data?.length ? ings.data.map(x => ({ quantity: x.quantity ?? '', unit: x.unit || '', name: x.name || '', notes: x.notes || '' })) : [emptyIngredient()]); setSteps(sts.data?.length ? sts.data.map(x => ({ instruction: x.instruction || '', duration_minutes: x.duration_minutes ?? '', temperature_celsius: x.temperature_celsius ?? '' })) : [emptyStep()]); } catch (e) { setError(e.message || 'Impossible de charger la recette.') } finally { setLoading(false) } }; loadRecipeForEdit() }, [recipeId, user?.id])
    const update = (field, value) => setForm(current => ({ ...current, [field]: value })); const updateIngredient = (index, field, value) => setIngredients(current => current.map((item, i) => i === index ? { ...item, [field]: value } : item)); const updateStep = (index, field, value) => setSteps(current => current.map((item, i) => i === index ? { ...item, [field]: value } : item)); const addIngredient = () => setIngredients(current => [...current, emptyIngredient()]); const removeIngredient = index => setIngredients(current => current.length === 1 ? current : current.filter((_, i) => i !== index)); const moveIngredient = (index, direction) => setIngredients(current => { const target = index + direction; if (target < 0 || target >= current.length) return current; const next = [...current]; [next[index], next[target]] = [next[target], next[index]]; return next }); const addStep = () => setSteps(current => [...current, emptyStep()]); const removeStep = index => setSteps(current => current.length === 1 ? current : current.filter((_, i) => i !== index)); const moveStep = (index, direction) => setSteps(current => { const target = index + direction; if (target < 0 || target >= current.length) return current; const next = [...current]; [next[index], next[target]] = [next[target], next[index]]; return next })
  const saveRecipe = async event => { event.preventDefault(); if (!supabase) return setError('La connexion Supabase n’est pas configurée.'); if (!form.title.trim()) return setError('Le nom de la recette est obligatoire.'); const validIngredients = ingredients.filter(item => item.name.trim()); const invalidIngredient = ingredients.some(item => item.name.trim() && item.quantity !== '' && Number.isNaN(Number(item.quantity))); const validSteps = steps.filter(item => item.instruction.trim()); if (invalidIngredient) return setError('Vérifiez les quantités des ingrédients.'); if (validSteps.length === 0) return setError('Ajoutez au moins une étape de préparation.'); setLoading(true); setError(''); try { const { data: membership, error: membershipError } = await supabase.from('family_members').select('id, family_id, role').eq('user_id', user.id).eq('is_active', true).limit(1).maybeSingle(); if (membershipError || !membership) throw new Error(membershipError?.message || 'Votre compte n’est associé à aucune famille active.'); if (!isEditing && !['admin', 'editor'].includes(membership.role)) throw new Error('Votre rôle ne permet pas de créer une recette.'); let recipe, version; if (isEditing) { const { data: existing, error: existingError } = await supabase.from('recipes').select('id,created_by').eq('id', recipeId).single(); if (existingError) throw existingError; if (membership.role !== 'admin' && membership.id !== existing.created_by) throw new Error('Vous ne pouvez pas modifier cette recette.'); const recipePayload = { category_id: form.category_id || '', title: form.title.trim(), description: form.description.trim(), original_author: form.original_author.trim(), origin_year: form.origin_year || '', difficulty: form.difficulty || '', servings: form.servings || '', preparation_time_minutes: form.preparation_time_minutes === '' ? '' : Number(form.preparation_time_minutes), cooking_time_minutes: form.cooking_time_minutes === '' ? '' : Number(form.cooking_time_minutes), tags: [...new Set(form.tags.split(',').map(tag => tag.trim()).filter(Boolean))] }; const ingredientPayload = validIngredients.map((item, index) => ({ position: index + 1, quantity: item.quantity === '' ? null : Number(item.quantity), unit: item.unit.trim(), name: item.name.trim(), notes: item.notes.trim() })); const stepPayload = validSteps.map((item, index) => ({ position: index + 1, instruction: item.instruction.trim(), duration_minutes: item.duration_minutes === '' ? null : Number(item.duration_minutes), temperature_celsius: item.temperature_celsius === '' ? null : Number(item.temperature_celsius) })); const { error: updateError } = await supabase.rpc('update_recipe_original', { p_recipe_id: recipeId, p_recipe: recipePayload, p_ingredients: ingredientPayload, p_steps: stepPayload }); if (updateError) throw updateError; recipe = existing; onCreated(recipe.id); return } else { const { data: createdRecipe, error: recipeError } = await supabase.from('recipes').insert({ family_id: membership.family_id, category_id: form.category_id || null, title: form.title.trim(), description: form.description.trim() || null, original_author: form.original_author.trim() || null, origin_year: form.origin_year ? Number(form.origin_year) : null, difficulty: form.difficulty || null, servings: form.servings ? Number(form.servings) : null, preparation_time_minutes: form.preparation_time_minutes === '' ? null : Number(form.preparation_time_minutes), cooking_time_minutes: form.cooking_time_minutes === '' ? null : Number(form.cooking_time_minutes), tags: [...new Set(form.tags.split(',').map(tag => tag.trim()).filter(Boolean))], created_by: membership.id }).select('id').single(); if (recipeError) throw recipeError; recipe = createdRecipe; const { data: createdVersion, error: versionError } = await supabase.from('recipe_versions').insert({ recipe_id: recipe.id, version_name: 'Version familiale', created_by: membership.id }).select('id').single(); if (versionError) throw versionError; version = createdVersion } if (validIngredients.length) { const { error } = await supabase.from('ingredients').insert(validIngredients.map((item, index) => ({ version_id: version.id, position: index + 1, quantity: item.quantity === '' ? null : Number(item.quantity), unit: item.unit.trim() || null, name: item.name.trim(), notes: item.notes.trim() || null }))); if (error) throw error } const { error: stepsError } = await supabase.from('preparation_steps').insert(validSteps.map((item, index) => ({ version_id: version.id, position: index + 1, instruction: item.instruction.trim(), duration_minutes: item.duration_minutes === '' ? null : Number(item.duration_minutes), temperature_celsius: item.temperature_celsius === '' ? null : Number(item.temperature_celsius) }))); if (stepsError) throw stepsError; onCreated(recipe.id) } catch (saveError) { setError(saveError.message || 'Une erreur est survenue pendant l’enregistrement.') } finally { setLoading(false) } }
  return <section className="form-section"><div className="form-header"><div><p className="section-kicker">{isEditing ? 'Modifier la recette' : 'Nouvelle recette'}</p><h2>{isEditing ? 'Modifier la recette familiale' : 'Ajouter une recette familiale'}</h2><p>{isEditing ? 'Corrigez les informations, les ingrédients ou les étapes de cette recette.' : 'Conservez la recette telle qu’elle est transmise, puis enrichissez-la avec ses ingrédients et ses étapes.'}</p></div><button type="button" className="secondary-button" onClick={onCancel}>Annuler</button></div><form className="recipe-form large-form" onSubmit={saveRecipe}><div className="form-grid"><label className="full-field">Nom de la recette *<input value={form.title} onChange={e => update('title', e.target.value)} required placeholder="Ex. Tarte aux pommes de Mamie" /></label><label>Catégorie<select value={form.category_id} onChange={e => update('category_id', e.target.value)}><option value="">Non classée</option>{categories.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label className="full-field">Tags<input value={form.tags} onChange={e => update('tags', e.target.value)} placeholder="Ex. rapide, enfants, Noël, thaï" /><span className="field-hint">Séparez les tags par des virgules.</span></label><label className="full-field">Description<textarea value={form.description} onChange={e => update('description', e.target.value)} rows="4" placeholder="Une courte présentation ou un souvenir lié à la recette…" /></label><label>Auteur d’origine<input value={form.original_author} onChange={e => update('original_author', e.target.value)} placeholder="Ex. Mamie" /></label><label>Année d’origine<input type="number" min="1800" max="2100" value={form.origin_year} onChange={e => update('origin_year', e.target.value)} placeholder="1987" /></label><label>Difficulté<select value={form.difficulty} onChange={e => update('difficulty', e.target.value)}><option value="">Non précisée</option><option value="facile">Facile</option><option value="moyenne">Moyenne</option><option value="difficile">Difficile</option></select></label><label>Nombre de personnes<input type="number" min="1" max="100" value={form.servings} onChange={e => update('servings', e.target.value)} placeholder="4" /></label><label>Préparation (min)<input type="number" min="0" value={form.preparation_time_minutes} onChange={e => update('preparation_time_minutes', e.target.value)} placeholder="20" /></label><label>Cuisson (min)<input type="number" min="0" value={form.cooking_time_minutes} onChange={e => update('cooking_time_minutes', e.target.value)} placeholder="45" /></label></div><section className="editor-section"><div className="editor-section-header"><div><p className="section-kicker">Les ingrédients</p><h3>De quoi avez-vous besoin ?</h3></div><button type="button" className="secondary-button" onClick={addIngredient}>＋ Ajouter un ingrédient</button></div><div className="ingredient-list">{ingredients.map((item, index) => <div className="ingredient-row" key={index}><span className="row-number">{index + 1}</span><input type="number" min="0" step="any" value={item.quantity} onChange={e => updateIngredient(index, 'quantity', e.target.value)} placeholder="Qté" aria-label={`Quantité ingrédient ${index + 1}`} /><input value={item.unit} onChange={e => updateIngredient(index, 'unit', e.target.value)} placeholder="Unité" aria-label={`Unité ingrédient ${index + 1}`} /><input className="name-input" value={item.name} onChange={e => updateIngredient(index, 'name', e.target.value)} placeholder="Ex. farine" aria-label={`Nom ingrédient ${index + 1}`} /><input className="notes-input" value={item.notes} onChange={e => updateIngredient(index, 'notes', e.target.value)} placeholder="Précision (optionnel)" aria-label={`Note ingrédient ${index + 1}`} /><div className="row-actions"><button type="button" onClick={() => moveIngredient(index, -1)} disabled={index === 0}>↑</button><button type="button" onClick={() => moveIngredient(index, 1)} disabled={index === ingredients.length - 1}>↓</button><button type="button" onClick={() => removeIngredient(index)} disabled={ingredients.length === 1}>×</button></div></div>)}</div></section><section className="editor-section"><div className="editor-section-header"><div><p className="section-kicker">La préparation</p><h3>Les étapes, dans l’ordre</h3></div><button type="button" className="secondary-button" onClick={addStep}>＋ Ajouter une étape</button></div><div className="step-list">{steps.map((step, index) => <div className="step-row" key={index}><div className="step-number">{index + 1}</div><textarea value={step.instruction} onChange={e => updateStep(index, 'instruction', e.target.value)} rows="3" placeholder="Décrivez cette étape…" /><div className="step-details"><input type="number" min="0" value={step.duration_minutes} onChange={e => updateStep(index, 'duration_minutes', e.target.value)} placeholder="Durée (min)" /><input type="number" min="0" step="any" value={step.temperature_celsius} onChange={e => updateStep(index, 'temperature_celsius', e.target.value)} placeholder="Température °C" /></div><div className="row-actions"><button type="button" onClick={() => moveStep(index, -1)} disabled={index === 0}>↑</button><button type="button" onClick={() => moveStep(index, 1)} disabled={index === steps.length - 1}>↓</button><button type="button" onClick={() => removeStep(index)} disabled={steps.length === 1}>×</button></div></div>)}</div></section>{error && <div className="form-error">{error}</div>}<div className="form-actions"><button type="button" className="secondary-button" onClick={onCancel}>Annuler</button><button type="submit" className="primary-button" disabled={loading}>{loading ? 'Enregistrement…' : isEditing ? 'Enregistrer les modifications' : 'Enregistrer la recette'}</button></div></form></section>
}

function App() {
  const [activePage, setActivePage] = useState('home'); const [selectedRecipeId, setSelectedRecipeId] = useState(null); const [selectedVersionId, setSelectedVersionId] = useState(null); const [user, setUser] = useState(null); const [role, setRole] = useState(null); const [authLoading, setAuthLoading] = useState(true); const [passwordOpen, setPasswordOpen] = useState(false); const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [confirmPassword, setConfirmPassword] = useState(''); const [passwordLoading, setPasswordLoading] = useState(false); const [passwordMessage, setPasswordMessage] = useState(''); const [passwordError, setPasswordError] = useState(''); const [recipes, setRecipes] = useState([]); const [recipesLoading, setRecipesLoading] = useState(false); const [recipesError, setRecipesError] = useState('')
  const canEdit = role === 'admin' || role === 'editor'
  useEffect(() => { if (!supabase) { setAuthLoading(false); return }; supabase.auth.getSession().then(({ data }) => { setUser(data.session?.user ?? null); setAuthLoading(false) }); const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => setUser(session?.user ?? null)); return () => listener.subscription.unsubscribe() }, [])
  useEffect(() => { let cancelled = false; const loadRole = async () => { if (!supabase || !user?.id) { setRole(null); return }; const { data, error } = await supabase.from('family_members').select('role').eq('user_id', user.id).eq('is_active', true).limit(1).maybeSingle(); if (!cancelled) setRole(error ? null : data?.role ?? null) }; loadRole(); return () => { cancelled = true } }, [user?.id])
  const loadRecipes = async () => { if (!supabase) { setRecipesError('La connexion Supabase n’est pas configurée.'); return }; setRecipesLoading(true); setRecipesError(''); const { data, error } = await supabase.from('recipes').select('id, category_id, title, description, original_author, origin_year, difficulty, servings, preparation_time_minutes, cooking_time_minutes, tags, created_at, categories(name)').order('created_at', { ascending: false }); if (error) { setRecipesError(error.message); setRecipes([]) } else setRecipes(data ?? []); setRecipesLoading(false) }
  useEffect(() => { if ((activePage === 'recipes' || activePage === 'grandma') && user) loadRecipes() }, [activePage, user])
  const goTo = pageId => { if (pageId === 'add-recipe' && !canEdit) return; setActivePage(pageId); if (pageId !== 'recipe-detail') setSelectedRecipeId(null); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const editRecipe = recipeId => { setSelectedRecipeId(recipeId); setActivePage('edit-recipe'); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const openRecipe = (recipeId, versionId = null) => { setSelectedRecipeId(recipeId); setSelectedVersionId(versionId); setActivePage('recipe-detail'); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const changePassword = async event => { event.preventDefault(); setPasswordError(''); setPasswordMessage(''); if (newPassword.length < 8) return setPasswordError('Le nouveau mot de passe doit contenir au moins 8 caractères.'); if (newPassword !== confirmPassword) return setPasswordError('Les deux nouveaux mots de passe ne correspondent pas.'); if (currentPassword === newPassword) return setPasswordError('Choisissez un mot de passe différent de l’ancien.'); setPasswordLoading(true); const { error } = await supabase.auth.updateUser({ email: user.email, current_password: currentPassword, password: newPassword }); setPasswordLoading(false); if (error) return setPasswordError(error.message === 'Invalid login credentials' ? 'Le mot de passe actuel est incorrect.' : error.message); setCurrentPassword(''); setNewPassword(''); setConfirmPassword(''); setPasswordMessage('Votre mot de passe a bien été modifié.'); window.setTimeout(() => { setPasswordOpen(false); setPasswordMessage('') }, 1200) }
  const signOut = async () => { await supabase?.auth.signOut(); setActivePage('home'); setSelectedRecipeId(null); setRole(null) }
  if (authLoading) return <div className="app"><main className="main-content"><div className="status-card">Chargement de votre livre…</div></main></div>
  if (!user) return <div className="app"><header className="app-header"><div className="header-inner"><div className="brand"><span className="brand-mark">🍲</span><span><span className="eyebrow">Notre livre de famille</span><span className="brand-title">Les recettes de notre famille</span></span></div></div></header><main className="main-content"><AuthPage onSignedIn={setUser} /></main><footer className="app-footer">Un patrimoine familial à préserver ❤️</footer></div>
  const page = pages[activePage]
  return <div className="app"><header className="app-header"><div className="header-inner"><button className="brand" type="button" onClick={() => goTo('home')} aria-label="Retour à l'accueil"><span className="brand-mark" aria-hidden="true">🍲</span><span><span className="eyebrow">Notre livre de famille</span><span className="brand-title">Les recettes de notre famille</span></span></button><nav className="desktop-nav" aria-label="Navigation principale">{navigation.map(item => <button key={item.id} type="button" className={activePage === item.id ? 'nav-button active' : 'nav-button'} onClick={() => goTo(item.id)}><span aria-hidden="true">{item.icon}</span>{item.label}</button>)}</nav><button className="profile-button" type="button" onClick={() => goTo('profile')} aria-label="Ouvrir mon profil" title="Mon profil">{user.email?.charAt(0).toUpperCase() || 'P'}</button></div></header><main className="main-content">{activePage === 'recipes' && <RecipesPage recipes={recipes} loading={recipesLoading} error={recipesError} onRetry={loadRecipes} onAdd={() => goTo('add-recipe')} onOpen={openRecipe} canEdit={canEdit} user={user} />}{activePage === 'grandma' && <GrandmaPage recipes={recipes} loading={recipesLoading} error={recipesError} onRetry={loadRecipes} onOpen={openRecipe} />}{activePage === 'recipe-detail' && selectedRecipeId && <RecipeDetailPage recipeId={selectedRecipeId} initialVersionId={selectedVersionId} user={user} onBack={() => goTo('recipes')} onEdit={editRecipe} />}{activePage === 'add-recipe' && canEdit && <AddRecipePage user={user} onCancel={() => goTo('recipes')} onCreated={openRecipe} />}{activePage === 'edit-recipe' && selectedRecipeId && <AddRecipePage user={user} recipeId={selectedRecipeId} onCancel={() => openRecipe(selectedRecipeId)} onCreated={openRecipe} />}{activePage === 'family' && <FamilyPage />}{activePage === 'favorites' && <FavoritesPage user={user} onOpen={openRecipe} />}{activePage === 'profile' && <section className="profile-page"><div className="profile-breadcrumb"><button type="button" onClick={() => goTo('home')}>Accueil</button><span>›</span><span>Mon compte</span></div><div className="profile-title"><h2>Mon profil</h2><p>Retrouvez les informations liées à votre compte familial.</p></div><div className="profile-layout"><article className="profile-identity-card"><div className="profile-identity-top"><div className="profile-avatar large" aria-hidden="true">{user.email?.charAt(0).toUpperCase() || 'P'}</div><div className="profile-person"><h3>{user.email?.split('@')[0]?.split(/[._-]/)[0]?.replace(/^./, char => char.toUpperCase()) || 'Membre'}</h3><p>{user.email}</p><span className="profile-role-badge">{role === 'admin' ? '♛ Administrateur' : role === 'editor' ? '✎ Éditeur' : 'Membre'}</span></div></div><div className="profile-details"><div className="profile-detail"><span className="profile-detail-icon" aria-hidden="true">✉</span><div><span>Adresse e-mail</span><strong>{user.email}</strong></div></div><div className="profile-detail"><span className="profile-detail-icon" aria-hidden="true">♙</span><div><span>Rôle dans la famille</span><strong>{role === 'admin' ? 'Administrateur' : role === 'editor' ? 'Éditeur' : 'Membre'}</strong><small>{role === 'admin' ? 'Vous pouvez ajouter, modifier et gérer les recettes et les membres.' : role === 'editor' ? 'Vous pouvez ajouter et modifier les recettes familiales.' : 'Vous pouvez consulter le livre de recettes familial.'}</small></div></div></div></article><div className="profile-side"><article className="profile-section-card settings-card"><div className="profile-card-title"><span aria-hidden="true">⚙</span><h3>Paramètres du compte</h3></div><div className="profile-setting-row"><span className="profile-setting-icon" aria-hidden="true">🔒</span><div><strong>Mot de passe</strong><small>La gestion du mot de passe sera disponible ici prochainement.</small></div><button type="button" onClick={() => { setPasswordOpen(true); setPasswordError(''); setPasswordMessage('') }}>Changer ›</button></div><div className="profile-setting-row"><span className="profile-setting-icon" aria-hidden="true">♢</span><div><strong>Notifications</strong><small>Les préférences de notification seront disponibles prochainement.</small></div><button type="button" disabled>Configurer ›</button></div></article><article className="profile-section-card logout-card"><div className="profile-card-title"><span aria-hidden="true">↪</span><h3>Déconnexion</h3></div><div className="profile-logout-row"><div><strong>Se déconnecter</strong><small>Vous serez déconnecté de votre session actuelle.</small></div><button type="button" className="profile-logout-button" onClick={signOut}>↪&nbsp; Se déconnecter</button></div></article></div></div><button type="button" className="profile-back-button" onClick={() => goTo('recipes')}>←&nbsp; Retour aux recettes</button>{passwordOpen && <div className="password-modal-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget && !passwordLoading) setPasswordOpen(false) }}><div className="password-modal" role="dialog" aria-modal="true" aria-labelledby="password-title"><button type="button" className="password-modal-close" onClick={() => setPasswordOpen(false)} aria-label="Fermer">×</button><p className="section-kicker">Sécurité du compte</p><h3 id="password-title">Changer le mot de passe</h3><p className="password-modal-intro">Saisissez votre mot de passe actuel, puis choisissez-en un nouveau.</p><form onSubmit={changePassword}><label>Mot de passe actuel<input type="password" autoComplete="current-password" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)} required /></label><label>Nouveau mot de passe<input type="password" autoComplete="new-password" minLength="8" value={newPassword} onChange={event => setNewPassword(event.target.value)} required /></label><label>Confirmer le nouveau mot de passe<input type="password" autoComplete="new-password" minLength="8" value={confirmPassword} onChange={event => setConfirmPassword(event.target.value)} required /></label>{passwordError && <p className="password-form-error" role="alert">{passwordError}</p>}{passwordMessage && <p className="password-form-success" role="status">{passwordMessage}</p>}<div className="password-modal-actions"><button type="button" className="secondary-button" onClick={() => setPasswordOpen(false)} disabled={passwordLoading}>Annuler</button><button type="submit" className="primary-button" disabled={passwordLoading}>{passwordLoading ? 'Modification…' : 'Modifier le mot de passe'}</button></div></form></div></div>}</section>}{activePage === 'home' && <><section className="hero"><p className="hero-kicker">{page.kicker}</p><h2>{page.title}</h2><p className="hero-text">{page.text}</p><div className="hero-actions"><button type="button" className="primary-button" onClick={() => goTo('recipes')}>Voir les recettes</button><button type="button" className="secondary-button" onClick={() => goTo('grandma')}>Recettes de Mamie</button></div></section><section className="section-preview"><div className="section-heading"><div><p className="section-kicker">À découvrir</p><h3>Votre livre de recettes</h3></div></div><div className="preview-grid"><button className="preview-card featured" type="button" onClick={() => goTo('grandma')}><span className="card-icon">📖</span><h4>Recettes de Mamie</h4><p>Les recettes originales et leurs documents manuscrits.</p></button><button className="preview-card" type="button" onClick={() => goTo('recipes')}><span className="card-icon">👨‍👩‍👧‍👦</span><h4>Recettes de la famille</h4><p>Les recettes partagées et enrichies par chacun.</p></button><button className="preview-card" type="button" onClick={() => goTo('favorites')}><span className="card-icon">❤️</span><h4>Mes favoris</h4><p>Retrouvez rapidement les recettes que vous aimez.</p></button></div></section></>}</main><nav className="mobile-nav" aria-label="Navigation mobile">{navigation.map(item => <button key={item.id} type="button" className={activePage === item.id ? 'mobile-nav-button active' : 'mobile-nav-button'} onClick={() => goTo(item.id)}><span className="mobile-nav-icon" aria-hidden="true">{item.icon}</span><span>{item.label}</span></button>)}</nav><footer className="app-footer">Un patrimoine familial à préserver ❤️</footer></div>
}

export default App
